package org.eclipse.search.internal.ui;

interface IDialogSettings {
    boolean getBoolean(String key);
    String get(String key);
}

class SearchPlugin {
    public static SearchPlugin getDefault() { return new SearchPlugin(); }
    public org.eclipse.jface.preference.IPreferenceStore getPreferenceStore() { return null; }
}

class SearchPreferencePage {
    public static boolean rememberLastUsedPage() { return false; }
}

public class SearchDialog {
    private IDialogSettings fDialogSettings;
    public static final String STORE_IS_OPEN_PREVIOUS_PAGE = "IS_OPEN_PREVIOUS_PAGE";

    public SearchDialog(IDialogSettings settings) {
        this.fDialogSettings = settings;
    }

    public boolean checkSetting() {
        return fDialogSettings.getBoolean(STORE_IS_OPEN_PREVIOUS_PAGE);
    }
}

